import { readFileSync } from 'node:fs';
import {
  test,
  expect,
  visit,
  expectView,
  noHorizontalOverflow,
} from './fixtures';
import { themeSchemes, views } from './matrix';

test.beforeAll(async ({ browser }, testInfo) => {
  if (testInfo.config.updateSnapshots !== 'none') {
    expect(
      process.env.CI,
      'Baseline candidates must be generated by CI in mcr.microsoft.com/playwright:v1.64.1-noble',
    ).toBeTruthy();
    expect(
      browser.browserType().executablePath(),
      'Use the pinned Playwright container browser',
    ).toMatch(/^\/ms-playwright\//);
    expect(readFileSync('/etc/os-release', 'utf8')).toMatch(
      /^VERSION_CODENAME=noble$/m,
    );
  }
});

for (const { theme, scheme } of themeSchemes) {
  for (const view of views) {
    test(`${theme.id} ${scheme} ${view}`, async ({ page, audit }, testInfo) => {
      await visit(page, { theme: theme.id, scheme, view });
      expect(await page.evaluate(() => window.devicePixelRatio)).toBe(
        testInfo.project.use.deviceScaleFactor,
      );
      await expectView(page, view);
      await expect(page.locator('html')).toHaveAttribute(
        'data-theme',
        theme.id,
      );
      await expect(page.locator('html')).toHaveAttribute(
        'data-bs-theme',
        scheme,
      );
      await noHorizontalOverflow(page);
      expect(
        audit.external,
        'Screenshots use deterministic simulation with no live calls',
      ).toHaveLength(0);
      await expect(page).toHaveScreenshot(`${theme.id}-${scheme}-${view}.png`, {
        fullPage: true,
        animations: 'disabled',
        caret: 'hide',
        scale: 'css',
      });
    });
  }
}
